<template>
  <section class="tab-panel mutual-comments" data-panel="mutualComments" :hidden="activeTab!=='mutualComments'" aria-label="互粉评论">
    <div class="fq-panel-root mc-card">
      <header class="fq-header"><div class="fq-header-title-wrap"><h2 class="fq-header-title">互粉评论</h2><span class="fq-header-subtitle">发现互关意愿 · 用评论建立联系</span></div><PanelActionBar class="fq-header-actions"><PanelIconButton :icon="RefreshCw" label="刷新记录" :disabled="busy" @click="refresh" /><PanelIconButton :icon="Settings" label="互粉评论设置" :disabled="!state" @click="openSettings" /><PanelIconButton :icon="Play" label="立即采集与打标" :disabled="busy||!state?.config.scanEnabled||state?.running.scan" @click="act('runScan')" /><PanelIconButton :icon="MessageCircle" label="立即评论" :disabled="busy||!state?.config.commentEnabled||state?.running.comment" @click="act('runComments')" /></PanelActionBar></header>
      <div v-if="error||state?.config.scanError||state?.config.commentError" class="fq-alert fq-alert-error" role="alert">{{ error||state.config.scanError||state.config.commentError }}</div><div v-if="notice" class="mc-notice" role="status">{{ notice }}</div>
      <div class="fq-summary-bar"><span class="fq-summary-item">总记录 <strong>{{ state?.allTotal||0 }}</strong></span><span v-for="key in summaryStates" :key="key" class="fq-summary-item">{{ status(key) }} <strong :class="'mc-count-'+key">{{ state?.counts?.[key]||0 }}</strong></span><span class="fq-summary-time">最近扫描：{{ date(state?.scans[0]?.at) }}</span></div>
      <div class="mc-schedules"><div v-for="phase in phases" :key="phase.key" class="mc-schedule"><span class="mc-dot" :class="{enabled:state?.config[phase.key+'Enabled']}"></span><strong>{{ phase.label }}</strong><span>{{ state?.running[phase.key]?'正在执行':state?.config[phase.key+'Enabled']?'下次 '+date(state.config[phase.key==='scan'?'nextScanAt':'nextCommentAt']):'已关闭' }}</span><span class="mc-budget">{{ phase.key==='scan'?'每批最多 '+(state?.config.batchSize||10)+' 帖':'每轮 '+(state?.config.perRun||3)+' 条 · 每日 '+(state?.config.dailyLimit||10)+' 条' }}</span></div></div>
      <div class="fq-filter-tabs mc-state-tabs" role="group" aria-label="评论状态筛选"><button v-for="key in ['all',...allStates]" :key="key" type="button" class="fq-filter-tab" :class="{active:statusFilter===key}" :aria-pressed="statusFilter===key" @click="statusFilter=key;changeFilter()">{{ key==='all'?'全部状态':status(key) }}</button></div>
      <div class="mc-list-toolbar"><div class="fq-filter-controls"><label class="mc-tag-filter">AI 标签<PanelSelect v-model="tagFilter" class="fq-select" aria-label="AI 标签筛选" @change="changeFilter"><option value="all">全部标签</option><option v-for="tag in tagKeys" :key="tag" :value="tag">{{ tagName(tag) }}（{{ state?.tags?.[tag]||0 }}）</option></PanelSelect></label><input v-model="query" class="fq-search-input" type="search" aria-label="搜索互粉评论" placeholder="搜索账号、原帖或评论…" @input="changeFilter"><span v-if="selected.size" class="mc-selection">已选 {{ selected.size }} 条 <button type="button" class="fq-btn fq-btn-secondary" @click="copySelected">复制原帖链接</button><button type="button" class="fq-btn fq-btn-secondary" @click="selected=new Set()">取消选择</button></span></div>
        <div class="monitor-pagination fq-pagination"><label class="fq-pagesize-label page-size-label">每页<PanelSelect v-model.number="pageSize" class="fq-select fq-pagesize-select" aria-label="每页条数" @change="changePageSize"><option v-for="n in [10,20,50,100]" :key="n" :value="n">{{ n }}</option></PanelSelect></label><span class="page-summary fq-page-summary">第 {{ state?.page||1 }} 页 · 共 {{ state?.total||0 }} 条</span><div class="page-actions fq-page-actions"><button class="icon-button secondary fq-page-nav-btn" aria-label="上一页" :disabled="page<=1||busy" @click="goPage(page-1)">‹</button><template v-for="(n,index) in pageNumbers" :key="index"><span v-if="n==='…'" class="fq-page-ellipsis">…</span><button v-else class="fq-page-btn" :class="{active:page===n}" :aria-label="'第 '+n+' 页'" :aria-current="page===n?'page':undefined" :disabled="busy" @click="goPage(n)">{{ n }}</button></template><button class="icon-button secondary fq-page-nav-btn" aria-label="下一页" :disabled="page>=totalPages||busy" @click="goPage(page+1)">›</button></div></div>
      </div>
      <div class="fq-table-wrap mc-table"><table class="fq-table"><colgroup><col class="mc-col-select"><col class="mc-col-source"><col class="mc-col-tag"><col class="mc-col-reply"><col class="mc-col-status"><col class="mc-col-time"><col class="mc-col-actions"></colgroup><thead><tr><th class="mc-center"><input type="checkbox" aria-label="选择本页全部记录" :checked="pageSelected" :indeterminate="selected.size>0&&!pageSelected" :disabled="!state?.items.length" @change="selectPage($event.target.checked)"></th><th>原帖</th><th class="mc-center">AI 标签</th><th>评论内容</th><th class="mc-center">评论状态</th><th class="mc-center">时间</th><th class="mc-center">操作</th></tr></thead><tbody><tr v-if="!state?.items.length"><td colspan="7" class="mc-empty">{{ !state?(error?'请保留已登录的 X 页面后刷新':'正在读取账号与记录…'):query||statusFilter!=='all'||tagFilter!=='all'?'没有符合筛选条件的记录':'暂无帖子记录。先开启采集与打标，再按需开启评论。' }}</td></tr><tr v-for="row in state?.items||[]" :key="row.postId" :class="{'fq-row-selected':selected.has(row.postId)}"><td class="mc-center"><input type="checkbox" :aria-label="'选择 @'+row.handle+' 的帖子'" :checked="selected.has(row.postId)" @change="toggleRow(row.postId,$event.target.checked)"></td><td><a class="mc-author" :href="row.url" target="_blank" rel="noopener noreferrer">@{{ row.handle }}</a><p class="mc-excerpt" :title="row.text">{{ row.text }}</p></td><td class="mc-center"><span class="mc-status" :class="'is-'+row.tag" :title="row.tagReason||'尚未完成 AI 打标'">{{ tagName(row.tag) }}</span></td><td><p class="mc-excerpt" :title="row.reply||row.error">{{ row.reply||row.error||(row.tag==='mutual'?'等待评论调度':'—') }}</p></td><td class="mc-center"><span class="mc-status" :class="'is-'+row.status">{{ status(row.status) }}</span></td><td class="mc-center mc-time">{{ date(row.finishedAt||row.createdAt) }}</td><td class="mc-center"><PanelIconButton :icon="ListTree" label="查看评论回溯" @click="openDetail(row)" /></td></tr></tbody></table></div>
    </div>
    <ActionSettingsDrawer ref="settingsDrawer" title="互粉评论设置">
      <div class="mc-form"><section v-for="phase in phases" :key="phase.key" class="mc-config-section"><h3>{{ phase.label }}</h3><p>{{ phase.key==='scan'?'定时读取首页新帖，批量识别互关意愿并入库。':'从已打标的互关帖中生成评论并发布，不主动关注。' }}</p><label><input v-model="draft[phase.key+'Enabled']" type="checkbox" @change="inspectEngine(phase.key)">{{ phase.key==='scan'?'采集开关':'评论开关' }}</label>
      <template v-if="draft[phase.key+'Enabled']"><label>AI 引擎<PanelSelect v-model="draft[phase.key+'Provider']" @change="inspectEngine(phase.key)"><option value="">请选择 AI 引擎</option><option v-for="engine in GENERATION_ENGINES" :key="engine.value" :value="engine.value">{{ engine.label }}</option></PanelSelect></label><label v-if="draft[phase.key+'Provider']==='grok-local'">生成 Bot<PanelSelect v-model="draft[phase.key+'BotId']"><option value="">请选择 Bot</option><option v-if="draft[phase.key+'BotId']&&!(engineStates[phase.key]?.bots||[]).some(bot=>bot.id===draft[phase.key+'BotId'])" :value="draft[phase.key+'BotId']">已保存的 Bot{{ engineMessages[phase.key]==='正在检测连接…'?'（检测中）':'（待确认连接）' }}</option><option v-for="bot in engineStates[phase.key]?.bots||[]" :key="bot.id" :value="bot.id">{{ bot.name }}</option></PanelSelect></label><p class="mc-engine-message" role="status">{{ engineMessages[phase.key] }}</p><div v-if="draft[phase.key+'Provider']&&draft[phase.key+'Provider']!=='grok'" class="mc-engine-actions"><button type="button" class="fq-btn fq-btn-secondary" @click="configureEngine(phase.key)">管理连接</button><button type="button" class="fq-btn fq-btn-secondary" @click="inspectEngine(phase.key)">重新检测</button></div></template>
      <label>执行间隔（分钟）<span class="mc-interval-range"><input v-model.number="draft[phase.key+'IntervalMinutes']" :aria-label="phase.label+'最短间隔'" type="number" min="1" max="1439"><span>至</span><input v-model.number="draft[phase.key+'IntervalMaxMinutes']" :aria-label="phase.label+'最长间隔'" type="number" min="2" max="1440"></span></label>
      <template v-if="phase.key==='scan'"><label>加载更多次数<InfoTip text="优先通过首页接口分页，相当于下拉加载。0 表示仅取首页第一批；遇到已保存的帖子锚点且整页没有新帖时提前结束。每次使用临时窗口，结束后关闭。" /><input v-model.number="draft.scrollRounds" type="number" min="0" max="30"></label><label>每批打标帖子数<InfoTip text="将多条新帖合并为一次 AI 请求，按引擎输入长度自动分批；已保存的标签不重复请求。" /><input v-model.number="draft.batchSize" type="number" min="1" max="100"></label></template>
      <template v-else><label>每轮评论上限<input v-model.number="draft.perRun" type="number" min="1" max="10"></label><label>每日评论上限<InfoTip text="按北京时间统计；待核实的发送也计入上限。发送之间随机间隔1至3分钟。" /><input v-model.number="draft.dailyLimit" type="number" min="1" max="1000"></label><label><input v-model="draft.followBackSuffixEnabled" type="checkbox">来关必回<InfoTip text="与关注队列一致，按评论语言追加互关邀请，例如：关注我，必回关！🤝。已有同义文案不重复；长度不足时保留草稿，不截断正文。" /></label><CommentTagsSettings :settings="draft" @update="Object.assign(draft,$event)" /></template></section></div><template #footer><p v-if="settingsError" class="mc-error mc-save-error" role="alert" tabindex="-1">{{ settingsError }}</p><button :disabled="busy" @click="save">{{ busy?'保存中…':'保存配置' }}</button></template>
    </ActionSettingsDrawer>
<PanelModal ref="saveResult" class="mc-save-result" title="保存成功"><p role="status">配置已保存到本机，刷新或重新打开后仍会保留。</p><template #footer><button type="button" @click="saveResult.close()">确定</button></template></PanelModal>
    <ActionSettingsDrawer ref="detailDrawer" title="评论回溯"><div v-if="detail" class="mc-detail"><p>{{ status(detail.status) }} · {{ date(detail.createdAt) }}</p><a :href="detail.url" target="_blank" rel="noopener noreferrer">打开 @{{ detail.handle }} 的原帖</a><h3>原帖内容</h3><p>{{ detail.text }}</p><h3>判断依据</h3><p>{{ tagName(detail.tag) }} · {{ detail.tagReason||'尚未完成判断' }}</p><p v-if="detail.tagBatchId" class="mc-time">打标批次：{{ detail.tagBatchId }} · {{ date(detail.taggedAt) }}</p><p v-if="detail.decorationSettings">随机标签：{{ detail.decorationSettings.quoteTagsEnabled?'已开启':'未开启' }} · 来关必回：{{ detail.decorationSettings.followBackSuffixEnabled?'已开启':'未开启' }}</p><h3>评论内容</h3><p>{{ detail.reply||'尚未生成' }}</p><p v-if="detail.knowledge?.wisdomVersion">参考智慧 v{{ detail.knowledge.wisdomVersion }}</p><p v-if="detail.knowledge?.warning">{{ detail.knowledge.warning }}</p><p v-if="detail.error" class="mc-error">{{ detail.error }}</p><a v-if="detail.publishedPostUrl" :href="detail.publishedPostUrl" target="_blank" rel="noopener noreferrer">查看已发布评论</a><button v-if="detail.status==='uncertain'&&detail.publishAttemptedAt" :disabled="busy" @click="act('verify',{postId:detail.postId})">核实发布结果</button><p v-if="tagBatch?.error" class="mc-error">打标：{{ tagBatch.error }}</p><details v-if="tagBatch?.raw"><summary>批量打标原始结果</summary><pre>{{ tagBatch.raw }}</pre></details><details v-if="detail.raw"><summary>AI 原始结果</summary><pre>{{ detail.raw }}</pre></details></div></ActionSettingsDrawer>
  </section>
</template>
<script setup>
import PanelSelect from "../components/PanelSelect.vue";
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';
import {Settings,Play,RefreshCw,ListTree,MessageCircle} from 'lucide';
import {panelNavigationController} from '../composables/usePanelNavigation.js';
import PanelActionBar from '../components/PanelActionBar.vue';
import PanelIconButton from '../components/PanelIconButton.vue';
import PanelModal from '../components/PanelModal.vue';
import ActionSettingsDrawer from '../components/ActionSettingsDrawer.vue';
import CommentTagsSettings from '../components/CommentTagsSettings.vue';
import InfoTip from '../components/InfoTip.vue';
import {GENERATION_ENGINES,inspectGenerationEngine} from '../generation-choice.js';
const {activeTab}=panelNavigationController;
const state=ref(null),busy=ref(false),error=ref(''),notice=ref(''),page=ref(1),draft=reactive({}),settingsError=ref(''),saveResult=ref(null),settingsDrawer=ref(null),detailDrawer=ref(null),detail=ref(null),tagBatch=ref(null);
const pageSize=ref([10,20,50,100].includes(Number(localStorage.getItem('mutualCommentsPageSize')))?Number(localStorage.getItem('mutualCommentsPageSize')):20),selected=ref(new Set());
const allStates=['idle','ready','generating','draft','publishing','posted','skipped','failed','uncertain'],summaryStates=['ready','generating','posted','failed','uncertain'];
const phases=[{key:'scan',label:'采集与打标'},{key:'comment',label:'互粉评论'}],tagKeys=['pending','tagging','mutual','not_mutual','uncertain','failed'];
const tagName=value=>({pending:'待打标',tagging:'打标中',mutual:'互关帖',not_mutual:'非互关帖',uncertain:'不确定',failed:'打标失败'}[value]||'待打标');
const totalPages=computed(()=>Math.max(1,Math.ceil((state.value?.total||0)/pageSize.value)));
const pageSelected=computed(()=>Boolean(state.value?.items.length)&&state.value.items.every(row=>selected.value.has(row.postId)));
const pageNumbers=computed(()=>{const pages=[...new Set([1,totalPages.value,page.value-1,page.value,page.value+1])].filter(n=>n>0&&n<=totalPages.value).sort((a,b)=>a-b),result=[];for(const n of pages){if(result.length&&n-pages[pages.indexOf(n)-1]>1)result.push('…');result.push(n);}return result;});
const query=ref(''),statusFilter=ref('all'),tagFilter=ref('all'),engineStates=reactive({}),engineMessages=reactive({});
let sequence=0;const engineSequence={scan:0,comment:0};
const date=value=>value?new Date(value).toLocaleString('sv-SE',{hour12:false}):'—';
const status=value=>({idle:'未入队',ready:'待评论',generating:'生成中',draft:'待发布',publishing:'发布中',posted:'已评论',skipped:'已跳过',failed:'未完成',uncertain:'待核实'}[value]||value);
const scanStatus=row=>row.status==='completed'?`采集 ${row.received} 条，新增 ${row.added} 条`:row.error||'扫描中';
async function request(action,extra={}){const result=await chrome.runtime.sendMessage({cmd:'mutualComments',action,...extra});if(!result?.ok)throw Error(result?.error||'请求失败');return result;}
async function refresh(){const ticket=++sequence;try{const result=await request('state',{page:page.value,pageSize:pageSize.value,status:statusFilter.value,tag:tagFilter.value,q:query.value});if(ticket!==sequence)return;if(state.value&&result.account.accountId!==state.value.account.accountId){settingsDrawer.value?.close();detailDrawer.value?.close();detail.value=null;}state.value=result;page.value=result.page;selected.value=new Set([...selected.value].filter(id=>result.items.some(row=>row.postId===id)));error.value='';if(detail.value)detail.value=result.items.find(row=>row.postId===detail.value.postId)||detail.value;}catch(e){if(ticket===sequence)error.value=e.message;}}
function changeFilter(){page.value=1;selected.value=new Set();refresh();}
function goPage(n){page.value=n;selected.value=new Set();refresh();}
function changePageSize(){localStorage.setItem('mutualCommentsPageSize',String(pageSize.value));changeFilter();}
function toggleRow(id,checked){const next=new Set(selected.value);checked?next.add(id):next.delete(id);selected.value=next;}
function selectPage(checked){selected.value=new Set(checked?(state.value?.items||[]).map(row=>row.postId):[]);}
async function copySelected(){try{await navigator.clipboard.writeText(state.value.items.filter(row=>selected.value.has(row.postId)).map(row=>row.url).join('\n'));notice.value='已复制所选原帖链接';}catch(e){error.value='复制失败：'+e.message;}}
async function act(action,extra={}){busy.value=true;error.value='';try{const result=await request(action,extra);notice.value=result.notice||'已安排扫描，执行进度会自动刷新';await refresh();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function openDetail(row){try{const result=await request('detail',{postId:row.postId});detail.value=result.row;tagBatch.value=result.tagBatch;detailDrawer.value.open();}catch(e){error.value=e.message;}}
function openSettings(){Object.assign(draft,state.value.config);settingsError.value='';settingsDrawer.value.open();for(const {key} of phases)if(draft[key+'Enabled'])inspectEngine(key);}
async function save(){busy.value=true;settingsError.value='';try{state.value=await request('save',{config:{...draft}});settingsDrawer.value.close();notice.value='两个调度的配置已保存';saveResult.value.open();}catch(e){settingsError.value=e.message;}finally{busy.value=false;}}
async function inspectEngine(phase){const ticket=++engineSequence[phase],provider=draft[phase+'Provider'];engineMessages[phase]='正在检测连接…';engineStates[phase]={};if(!provider){engineMessages[phase]='请选择 AI 引擎';return;}try{const result=await inspectGenerationEngine(provider);if(ticket!==engineSequence[phase])return;engineStates[phase]=result;if(provider==='grok-local'&&!draft[phase+'BotId'])draft[phase+'BotId']=result.bot||'';engineMessages[phase]=result.ready?'引擎可用':'请先配置连接';}catch(e){if(ticket===engineSequence[phase])engineMessages[phase]=e.message;}}
function configureEngine(phase){document.dispatchEvent(new CustomEvent(draft[phase+'Provider']==='grok-local'?'xfollower:bind-grok-local':'xfollower:bind-grok-bot'));}
watch(activeTab,tab=>{if(tab==='mutualComments')refresh();},{immediate:true});
const timer=setInterval(()=>{if(activeTab.value==='mutualComments'&&!busy.value)refresh();},5000);
onBeforeUnmount(()=>{clearInterval(timer);sequence++;});
</script>
<style scoped>
